describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("compounds discounts sequentially on remaining subtotal", () => {
      // 10% of 10000 = 1000, then 10% of 9000 = 900 → total 1900
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      // fixed 500 first → remaining 9500, then 10% of 9500 = 950 → total 1450
      const fixedFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 10000 = 1000 first → remaining 9000, then fixed 500 → total 1500
      const percentFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(fixedFirst.computeDiscountCents(10000)).toBe(1450);
      expect(percentFirst.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops accumulating when remaining hits zero", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      // subtotal 800: first takes 800 (capped), remaining 0, second gets 0
      expect(composite.computeDiscountCents(800)).toBe(800);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

