      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
      expect(cart.totals().subtotalCents).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes subtotal as sum of (unitPrice * qty)", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2500
      expect(cart.totals().subtotalCents).toBe(4500);
    });

    it("returns all-zero totals for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });

    it("applies discount, then tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(400),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
      });
      cart.add(productA, 5); // subtotal = 5000
      const t = cart.totals();

      expect(t.subtotalCents).toBe(5000);
      expect(t.discountCents).toBe(500);
      // tax should receive discounted subtotal = 4500
      expect(tax.computeTaxCents).toHaveBeenCalledWith(4500, "US");
      expect(t.taxCents).toBe(400);
      expect(t.totalCents).toBe(4500 + 400);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal = 1000
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negativeDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: negativeDiscount });
      cart.add(productA, 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("includes shipping in the total", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(productA, 1); // subtotal = 1000
      const t = cart.totals();
      expect(t.shippingCents).toBe(799);
      expect(t.totalCents).toBe(1000 + 799);
    });

    it("passes discounted subtotal to shipping calculator", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(productA, 1); // subtotal = 1000, discounted = 800
      cart.totals();
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
    });

    it("uses default region US", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(productA, 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });

    it("respects custom region", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(productA, 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2 * 1000 + 2500);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1100) // productA new price
          .mockResolvedValueOnce(2600), // productB new price
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(2 * 1100 + 2600);
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
    });

    it("throws InventoryError when item is unavailable", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.message).toBe("sold out");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // productA requested 2
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(1);
      }
    });

    it("succeeds when inventory is sufficient", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 100,
        }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(4500);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1), // 10%
      };
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(300),
      };
      const taxCart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      taxCart.add(productA, 5); // subtotal = 5000
      const result = await taxCart.checkout({ asyncTaxProvider });

      // discounted subtotal = 5000 - 500 = 4500
      // tax = 10% of 4500 = 450
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(450);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(4500 + 450 + 300);
    });

    it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider,
      });
      // subtotal: (2*1000) + (1*1000) = 3000 (all refreshed to 1000)
      expect(result.totals.subtotalCents).toBe(3000);
      // 5% of 3000 = 150
      expect(result.totals.taxCents).toBe(150);
    });

    it("propagates priceFetcher error", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });

    it("propagates asyncTaxProvider error", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
      };
      await expect(
        cart.checkout({ asyncTaxProvider }),
      ).rejects.toThrow("tax service error");
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 5000, 999999])(
    "returns 0 for subtotal %i",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects invalid percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  it("computes 10% of 10000 cents", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down to nearest cent", () => {
    const policy = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 exactly
    expect(policy.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → floor = 33
    expect(policy.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("100% discount equals subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(5000)).toBe(5000);
  });

  it("0% discount returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amount %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps discount at subtotal when fixed amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(300)).toBe(300);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("compounds discounts sequentially on remaining subtotal", () => {
      // 10% of 10000 = 1000, then 10% of 9000 = 900 → total 1900
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      // fixed 500 first → remaining 9500, then 10% of 9500 = 950 → total 1450
      const fixedFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 10000 = 1000 first → remaining 9000, then fixed 500 → total 1500
      const percentFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(fixedFirst.computeDiscountCents(10000)).toBe(1450);
      expect(percentFirst.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops accumulating when remaining hits zero", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      // subtotal 800: first takes 800 (capped), remaining 0, second gets 0
      expect(composite.computeDiscountCents(800)).toBe(800);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

