  });

  it("selects the first bracket that covers the weight", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // 400g → first bracket (≤500g) → 300 cents
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 100)).toBe(300);
  });

  it("selects bracket at exact boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // exactly 500g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 100)).toBe(300);
    // exactly 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501, 1)], 100)).toBe(500);
    // exactly 1000g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 100)).toBe(500);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(brackets, 2000);
    // 6000g > 5000g → overflow = 2000
    expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 100)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // 6000g > 5000g → heaviest bracket cost = 1000
    expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 100)).toBe(1000);
  });

  it("sorts brackets internally regardless of input order", () => {
    const unordered = [
      { upToGrams: 5000, costCents: 1000 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ];
    const calc = new WeightBasedShippingCalculator(unordered);
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 100)).toBe(300);
  });

  it("accumulates weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // 300g * 2 = 600g → second bracket (≤1000g) → 500
    const lines = [makeLine("a", 300, 2)];
    expect(calc.computeShippingCents(lines, 100)).toBe(500);
  });
});

import { describe, it, expect, vi } from "vitest";
